WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') bom_code,coalesce(%s::text,'') product_code,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT row_number() OVER(ORDER BY h.date_change DESC,h.time_change DESC) stt,h.product_code,v.ten_vt,h.bom_code,h.ver,h.date_change,h.time_change,h.user_change,h.type_change,h.content_change,h.status,count(*) OVER() total FROM public.history_bom_change h LEFT JOIN public.dmvt v ON v.ma_vt=h.product_code LEFT JOIN public.mfbom b ON b.bom_code=h.bom_code CROSS JOIN s WHERE s.ok IS NOT NULL AND h.date_change BETWEEN s.d1 AND s.d2 AND (s.bom_code='' OR h.bom_code=ANY(string_to_array(s.bom_code,','))) AND (s.product_code='' OR h.product_code=ANY(string_to_array(s.product_code,','))) AND (s.all_branch OR coalesce(b.branch_list,'')='' OR EXISTS(SELECT 1 FROM unnest(string_to_array(s.bs,',')) x WHERE x=ANY(string_to_array(b.branch_list,',')))) ORDER BY h.date_change DESC,h.time_change DESC LIMIT (SELECT lim FROM p);
